const encoder=new TextEncoder();
function checksum(b){let c=-1;for(const x of b){c^=x;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^-1)>>>0;}
async function zip(entries){let offset=0;const parts=[],directory=[];for(const [name,blob] of entries){const n=encoder.encode(name),b=new Uint8Array(await blob.arrayBuffer()),crc=checksum(b),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,2048,true);v.setUint32(14,crc,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,n.length,true);h.set(n,30);parts.push(h,b);const c=new Uint8Array(46+n.length),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,2048,true);w.setUint32(16,crc,true);w.setUint32(20,b.length,true);w.setUint32(24,b.length,true);w.setUint16(28,n.length,true);w.setUint32(42,offset,true);c.set(n,46);directory.push(c);offset+=h.length+b.length;}const end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,directory.reduce((s,b)=>s+b.length,0),true);v.setUint32(16,offset,true);return new Blob([...parts,...directory,end],{type:'application/zip'});}
export async function markdownBundle(title,records,getMedia){const files=[],paths=new Map(),esc=s=>String(s||'').replace(/([\\`*_{}\[\]<>#!|])/g,'\\$1');async function media(mid,label,image=true){if(!paths.has(mid)){const b=await getMedia(mid);if(!(b instanceof Blob)||!b.size)throw new Error('附件缺失或为空，导出停止');const ext=(!image&&label?.match(/\.([a-zA-Z0-9]{1,12})$/)?.[1]?.toLowerCase())||({'image/png':'png','image/jpeg':'jpg','image/webp':'webp','video/mp4':'mp4','video/webm':'webm'})[b.type]||'bin',path=`attachments/${paths.size+1}.${ext}`;paths.set(mid,path);files.push([path,b]);}return `${image?'!':''}[${esc(label||'附件')}](${paths.get(mid)})`;}
const out=['# '+esc(title),'','> 可读导出；完整恢复使用 JSON。手写仅导出预览。',''];function tree(rows,depth=0){return rows.flatMap(r=>[{...r,exportDepth:depth},...(r.children?tree(r.children,depth+1):[])]);}for(const r of tree([...records].sort((a,b)=>a.created-b.created||String(a.id).localeCompare(String(b.id))))){out.push('#'.repeat(Math.min(6,2+r.exportDepth))+' '+(r.origin?(r.origin.sender||'未知发送者')+' · '+(r.origin.time||'原时间未提供'):new Date(r.created).toLocaleString('zh-CN')),'');if(r.origin)out.push('导入时间：'+new Date(r.origin.importedAt).toLocaleString('zh-CN'),'');if(['image','video','handwriting'].includes(r.type))out.push(await media(r.id,r.name,r.type!=='video'));else if(r.type==='richtext'){const t=document.createElement('template');t.innerHTML=r.html||'';for(const img of t.content.querySelectorAll('img'))img.replaceWith(document.createTextNode(await media(img.dataset.media,img.alt)));for(const br of t.content.querySelectorAll('br'))br.replaceWith('\n');for(const p of t.content.querySelectorAll('p,h2,li,blockquote'))p.append('\n');out.push(t.content.textContent);}else {out.push((r.type==='task'?`- [${r.done?'x':' '}] `:'')+esc(r.text));if(r.dueDate)out.push('截止：'+r.dueDate);if(r.reminderDate||r.reminderTime)out.push('提醒偏好：'+[r.reminderDate,r.reminderTime].filter(Boolean).join(' '));for(const mid of r.images||[])out.push(await media(mid,'待办图片'));}for(const a of r.attachments||[])out.push(await media(a.id,a.name,false));out.push('');}const name=String(title||'自言导出').replace(/[\x00-\x1f<>:"/\\|?*]/g,'_').replace(/^\.+|[. ]+$/g,'').slice(0,80)||'自言导出',md=new Blob([out.join('\n')],{type:'text/markdown;charset=utf-8'});return files.length?{name:name+'.zip',blob:await zip([[name+'.md',md],...files])}:{name:name+'.md',blob:md};}
